// CLO-019 (audit 2026-05-26): Apollo enrichment is opt-in.
// Short-circuit unless either (a) caller passed manual_trigger=true, OR
// (b) system_config.lead_auto_enrich_enabled='true'.
const SR = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const __body = ($input.first() && $input.first().json) || {};
const __manual = __body.manual_trigger === true || __body.manual_trigger === 'true';
let __auto = false;
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/system_config?key=eq.lead_auto_enrich_enabled&select=value',
    headers: { 'apikey': SR, 'Authorization': 'Bearer ' + SR, 'Accept': 'application/json' },
    json: true,
    timeout: 5000,
  });
  const arr = Array.isArray(resp) ? resp : (resp && resp.data ? resp.data : []);
  __auto = arr[0] && (arr[0].value === 'true' || arr[0].value === true);
} catch (e) { __auto = false; }
if (!__manual && !__auto) {
  return [{ json: { skipped: true, reason: 'CLO-019: Apollo enrichment is opt-in (lead_auto_enrich_enabled=false and manual_trigger not set)' } }];
}

const people = $input.item.json.people || [];
const person = people[0] || {};
const org = person.organization || {};
return [{ json: { email: person.email || null, linkedin: person.linkedin_url || null, title: person.title || null, seniority: person.seniority || null, company_size: org.estimated_num_employees || null, industry: org.industry || null } }];

// Injected fetch-based httpRequest shim (task-runner-safe)
const __helpers = this.helpers;
async function __httpRequest(opts) {
  const method = (opts.method || 'GET').toUpperCase();
  const url = opts.url;
  const headers = Object.assign({}, opts.headers || {});
  const cfg = {
    method,
    url,
    headers,
    json: opts.json !== false,
    returnFullResponse: true,
    timeout: opts.timeout || 30000,
  };
  if (opts.body !== undefined && opts.body !== null) {
    cfg.body = opts.body;
    if (typeof opts.body === 'object' && !headers['Content-Type'] && !headers['content-type']) {
      cfg.headers['Content-Type'] = 'application/json';
    }
  }
  let res;
  try {
    res = await __helpers.httpRequest(cfg);
  } catch (err) {
    const status = err.httpCode || err.statusCode || (err.response && err.response.status) || 0;
    const body = (err.response && err.response.body) || err.body || null;
    const wrapped = new Error('HTTP ' + (status || 'network') + ': ' + (err.message || String(err)).slice(0, 300));
    wrapped.httpCode = status;
    wrapped.body = body;
    throw wrapped;
  }
  const status = res.statusCode || res.status || 0;
  const body = res.body !== undefined ? res.body : res;
  if (status < 200 || status >= 300) {
    const e = new Error('HTTP ' + status + ': ' + String(body).slice(0, 300));
    e.httpCode = status;
    e.body = body;
    throw e;
  }
  return body;
}

let startTime = Date.now();
try {
  startTime = $('Webhook').first().json.headers['x-request-start'];
} catch(e) {
  // Ignore missing webhook node
}
const duration = Date.now() - (parseInt(startTime) || Date.now());

const payload = {
  workflow_id: $workflow.id,
  workflow_name: $workflow.name,
  agent_id: $input.first()?.json?.agent_id || 'system',
  duration_ms: duration,
